func (o *GameServer) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "FederatedAccessGrants":
		rels, ok := retrieved.(FederatedAccessGrantSlice)
		if !ok {
			return fmt.Errorf("gameServer cannot load %T as %q", retrieved, name)
		}

		o.R.FederatedAccessGrants = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.GameServer = o
			}
		}
		return nil
	case "Node":
		rel, ok := retrieved.(*Node)
		if !ok {
			return fmt.Errorf("gameServer cannot load %T as %q", retrieved, name)
		}

		o.R.Node = rel

		if rel != nil {
			rel.R.GameServers = GameServerSlice{o}
		}
		return nil
	case "IP":
		rel, ok := retrieved.(*IP)
		if !ok {
			return fmt.Errorf("gameServer cannot load %T as %q", retrieved, name)
		}

		o.R.IP = rel

		if rel != nil {
			rel.R.GameServers = GameServerSlice{o}
		}
		return nil
	case "Game":
		rel, ok := retrieved.(*Game)
		if !ok {
			return fmt.Errorf("gameServer cannot load %T as %q", retrieved, name)
		}

		o.R.Game = rel

		if rel != nil {
			rel.R.GameServers = GameServerSlice{o}
		}
		return nil
	case "User":
		rel, ok := retrieved.(*User)
		if !ok {
			return fmt.Errorf("gameServer cannot load %T as %q", retrieved, name)
		}

		o.R.User = rel

		if rel != nil {
			rel.R.GameServers = GameServerSlice{o}
		}
		return nil
	case "GameServerMetricsHistories":
		rels, ok := retrieved.(GameServerMetricsHistorySlice)
		if !ok {
			return fmt.Errorf("gameServer cannot load %T as %q", retrieved, name)
		}

		o.R.GameServerMetricsHistories = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.GameServer = o
			}
		}
		return nil
	case "InstalledMods":
		rels, ok := retrieved.(InstalledModSlice)
		if !ok {
			return fmt.Errorf("gameServer cannot load %T as %q", retrieved, name)
		}

		o.R.InstalledMods = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.GameServer = o
			}
		}
		return nil
	case "Logs":
		rels, ok := retrieved.(LogSlice)
		if !ok {
			return fmt.Errorf("gameServer cannot load %T as %q", retrieved, name)
		}

		o.R.Logs = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.GameServer = o
			}
		}
		return nil
	case "UserRoleAssignments":
		rels, ok := retrieved.(UserRoleAssignmentSlice)
		if !ok {
			return fmt.Errorf("gameServer cannot load %T as %q", retrieved, name)
		}

		o.R.UserRoleAssignments = rels

		for _, rel := range rels {
			if rel != nil {
				rel.R.GameServer = o
			}
		}
		return nil
	default:
		return fmt.Errorf("gameServer has no relationship %q", name)
	}
}

