type gameServerJoins[Q dialect.Joinable] struct {
	typ                        string
	FederatedAccessGrants      modAs[Q, federatedAccessGrantColumns]
	Node                       modAs[Q, nodeColumns]
	IP                         modAs[Q, ipColumns]
	Game                       modAs[Q, gameColumns]
	User                       modAs[Q, userColumns]
	GameServerMetricsHistories modAs[Q, gameServerMetricsHistoryColumns]
	InstalledMods              modAs[Q, installedModColumns]
	Logs                       modAs[Q, logColumns]
	UserRoleAssignments        modAs[Q, userRoleAssignmentColumns]
}

func (j gameServerJoins[Q]) aliasedAs(alias string) gameServerJoins[Q] {
	return buildGameServerJoins[Q](buildGameServerColumns(alias), j.typ)
}

func buildGameServerJoins[Q dialect.Joinable](cols gameServerColumns, typ string) gameServerJoins[Q] {
	return gameServerJoins[Q]{
		typ: typ,
		FederatedAccessGrants: modAs[Q, federatedAccessGrantColumns]{
			c: FederatedAccessGrants.Columns,
			f: func(to federatedAccessGrantColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, FederatedAccessGrants.Name().As(to.Alias())).On(
						to.GameServerID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Node: modAs[Q, nodeColumns]{
			c: Nodes.Columns,
			f: func(to nodeColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Nodes.Name().As(to.Alias())).On(
						to.ID.EQ(cols.NodeID),
					))
				}

				return mods
			},
		},
		IP: modAs[Q, ipColumns]{
			c: Ips.Columns,
			f: func(to ipColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Ips.Name().As(to.Alias())).On(
						to.Address.EQ(cols.IP),
					))
				}

				return mods
			},
		},
		Game: modAs[Q, gameColumns]{
			c: Games.Columns,
			f: func(to gameColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Games.Name().As(to.Alias())).On(
						to.ID.EQ(cols.GameID),
					))
				}

				return mods
			},
		},
		User: modAs[Q, userColumns]{
			c: Users.Columns,
			f: func(to userColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Users.Name().As(to.Alias())).On(
						to.ID.EQ(cols.UserID),
					))
				}

				return mods
			},
		},
		GameServerMetricsHistories: modAs[Q, gameServerMetricsHistoryColumns]{
			c: GameServerMetricsHistories.Columns,
			f: func(to gameServerMetricsHistoryColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, GameServerMetricsHistories.Name().As(to.Alias())).On(
						to.GameServerID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		InstalledMods: modAs[Q, installedModColumns]{
			c: InstalledMods.Columns,
			f: func(to installedModColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, InstalledMods.Name().As(to.Alias())).On(
						to.GameServerID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Logs: modAs[Q, logColumns]{
			c: Logs.Columns,
			f: func(to logColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Logs.Name().As(to.Alias())).On(
						to.GameServerID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		UserRoleAssignments: modAs[Q, userRoleAssignmentColumns]{
			c: UserRoleAssignments.Columns,
			f: func(to userRoleAssignmentColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, UserRoleAssignments.Name().As(to.Alias())).On(
						to.GameServerID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
